package com.echovault.servlet;
import com.echovault.dao.CapsuleDAO;import com.echovault.model.Capsule;import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.*;
@WebServlet("/capsule") public class ViewCapsuleServlet extends HttpServlet{protected void doGet(HttpServletRequest q,HttpServletResponse s)throws ServletException,IOException{HttpSession h=q.getSession(false);if(h==null||h.getAttribute("userId")==null){s.sendRedirect("login.jsp");return;}try{int id=Integer.parseInt(q.getParameter("id"));CapsuleDAO d=new CapsuleDAO();Capsule c=d.findVisible(id,(Integer)h.getAttribute("userId"),(String)h.getAttribute("userEmail"));if(c==null){s.sendError(404);return;}if(!c.isUnlocked()){q.setAttribute("locked",true);}else{q.setAttribute("memories",d.memories(id));}q.setAttribute("capsule",c);q.getRequestDispatcher("capsule.jsp").forward(q,s);}catch(NumberFormatException e){s.sendError(400);}catch(Exception e){throw new ServletException(e);}}}